{"command": "cat > /prediction.json << 'EOF'
{
    "vllm/v1/spec_decode/utils.py": {
        "eagle_prepare_next_token_padded_kernel": "@triton.jit\ndef eagle_prepare_next_token_padded_kernel(\n    sampled_token_ids_ptr,  # [num_reqs, num_sampled_tokens_per_req]\n    discard_request_mask_ptr,  # [num_reqs]\n    backup_next_token_ids_ptr,  # [num_reqs]\n    next_token_ids_ptr,  # [num_reqs] (output)\n    valid_sampled_tokens_count_ptr,  # [num_reqs] (output)\n    vocab_size,  # tl.int32\n    num_sampled_tokens_per_req,  # tl.int32 (num_spec_tokens + 1)\n    num_reqs,  # tl.int32\n    stride_sampled_token_ids,  # tl.int32 (stride for dim 0)\n    BLOCK_SIZE_TOKENS: tl.constexpr,  # Power-of-2 >= num_sampled_tokens_per_req\n):\n    # Each program processes one request\n    req_idx = tl.program_id(0)\n    \n    if req_idx >= num_reqs:\n        return\n    \n    # Check if request is discarded using mask\n    is_discarded = tl.load(discard_request_mask_ptr + req_idx) != 0\n    \n    # Initialize counters\n    valid_count = 0\n    last_valid_token = -1\n    last_valid_index = -1\n    \n    # Process tokens in this request\n    for token_offset in range(0, num_sampled_tokens_per_req, BLOCK_SIZE_TOKENS):\n        # Create mask for valid token offsets\n        token_mask = token_offset + tl.arange(0, BLOCK_SIZE_TOKENS) < num_sampled_tokens_per_req\n        \n        # Load token IDs for this block\n        token_ids = tl.load(\n            sampled_token_ids_ptr + req_idx * stride_sampled_token_ids + token_offset,\n            mask=token_mask,\n            other=-1\n        )\n        \n        # If request is discarded, all tokens are invalid\n        if is_discarded:\n            valid_mask = tl.zeros(BLOCK_SIZE_TOKENS, dtype=tl.int1)\n        else:\n            # Check validity: token != -1 and token < vocab_size\n            valid_mask = (token_ids != -1) & (token_ids < vocab_size)\n        \n        # Count valid tokens in this block\n        block_valid_count = tl.sum(valid_mask.to(tl.int32))\n        valid_count += block_valid_count\n        \n        # Find the last valid token in this block\n        # Create indices for this block\n        block_indices = token_offset + tl.arange(0, BLOCK_SIZE_TOKENS)\n        \n        # Only consider valid positions\n        valid_positions = tl.where(valid_mask, block_indices, -1)\n        # Get the maximum valid position in this block\n        max_valid_pos = tl.max(valid_positions)\n        \n        if max_valid_pos >= 0:\n            # Update last valid index\n            last_valid_index = max_valid_pos\n            # Get the token at this position\n            last_valid_token = tl.load(\n                sampled_token_ids_ptr + req_idx * stride_sampled_token_ids + max_valid_pos\n            )\n    \n    # Store valid count\n    tl.store(valid_sampled_tokens_count_ptr + req_idx, valid_count)\n    \n    # Determine next token ID\n    if last_valid_index >= 0:\n        # Use the last valid token\n        next_token_id = last_valid_token\n    else:\n        # Use backup token\n        next_token_id = tl.load(backup_next_token_ids_ptr + req_idx)\n    \n    # Store next token ID\n    tl.store(next_token_ids_ptr + req_idx, next_token_id)",
        "eagle_prepare_inputs_padded_kernel": "@triton.jit\ndef eagle_prepare_inputs_padded_kernel(\n    cu_num_draft_tokens_ptr,  # [num_reqs]\n    valid_sampled_tokens_count_ptr,  # [num_reqs]\n    query_start_loc_gpu_ptr,  # [num_reqs + 1]\n    token_indices_to_sample_ptr,  # [num_reqs] (output)\n    num_reqs,  # tl.int32\n):\n    # Each program processes one request\n    req_idx = tl.program_id(0)\n    \n    if req_idx >= num_reqs:\n        return\n    \n    # Load cumulative number of draft tokens for this request\n    # For the first request, we need to handle it specially\n    if req_idx == 0:\n        num_draft_tokens = tl.load(cu_num_draft_tokens_ptr)\n    else:\n        # Current minus previous to get number of draft tokens for this request\n        current = tl.load(cu_num_draft_tokens_ptr + req_idx)\n        previous = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n        num_draft_tokens = current - previous\n    \n    # Load valid sampled tokens count for this request\n    valid_count = tl.load(valid_sampled_tokens_count_ptr + req_idx)\n    \n    # Load query start locations\n    query_start = tl.load(query_start_loc_gpu_ptr + req_idx)\n    query_end = tl.load(query_start_loc_gpu_ptr + req_idx + 1)\n    \n    # Compute number of rejected tokens\n    # If there are draft tokens, rejected = draft_tokens + 1 - valid_count\n    # Otherwise, rejected = 0\n    num_rejected_tokens = tl.where(\n        num_draft_tokens > 0,\n        num_draft_tokens + 1 - valid_count,\n        0\n    )\n    \n    # Compute token_indices_to_sample\n    # query_end - 1 gives the last token index\n    # Subtract num_rejected_tokens to get the token index to sample\n    token_index_to_sample = query_end - 1 - num_rejected_tokens\n    \n    # Store the result\n    tl.store(token_indices_to_sample_ptr + req_idx, token_index_to_sample)"
    }
}
EOF"}

